sourceCode['combobox.tsx'] = ''
  + 'import classNames from "classnames";\n'
  + 'import { debounce } from "es-toolkit";\n'
  + 'import {\n'
  + '  useCallback,\n'
  + '  useEffect,\n'
  + '  useLayoutEffect,\n'
  + '  useRef,\n'
  + '  useState,\n'
  + '} from "react";\n'
  + '\n'
  + 'import { useJss, useTheme } from "@/components/CopyUiProvider";\n'
  + 'import { Popover, type PopoverTriggerRender } from "@/components/Popover";\n'
  + 'import { resolveStyle2 } from "@/utils/resolve-style2";\n'
  + '\n'
  + 'import { ComboboxList } from "./combobox-list";\n'
  + 'import { ComboboxTrigger } from "./combobox-trigger";\n'
  + '\n'
  + 'interface ComboboxProps<V extends string> {\n'
  + '  id?: string;\n'
  + '  value?: V | null;\n'
  + '  defaultValue?: V | null;\n'
  + '\n'
  + '  width?: "sm" | "md" | "lg" | "full";\n'
  + '\n'
  + '  optionsLoader: (query: string) => Promise<Array<{ value: V; label: string }>>;\n'
  + '  placeholder?: string;\n'
  + '  disabled?: boolean;\n'
  + '\n'
  + '  onChange?: (value: V) => void;\n'
  + '}\n'
  + '\n'
  + 'const Combobox = <V extends string>(props: ComboboxProps<V>) => {\n'
  + '  const {\n'
  + '    id,\n'
  + '    value = null,\n'
  + '    defaultValue = null,\n'
  + '    width = "md",\n'
  + '    optionsLoader,\n'
  + '    placeholder = "Search...",\n'
  + '    disabled = false,\n'
  + '    onChange,\n'
  + '  } = props;\n'
  + '\n'
  + '  const jss = useJss();\n'
  + '  const theme = useTheme();\n'
  + '\n'
  + '  const [triggerEl, setTriggerEl] = useState<HTMLButtonElement | null>(null);\n'
  + '  const [internalValue, setInternalValue] = useState<V | null>(defaultValue);\n'
  + '  const [triggerWidth, setTriggerWidth] = useState(0);\n'
  + '  const [searchQuery, setSearchQuery] = useState("");\n'
  + '  const [options, setOptions] = useState<Array<{ value: V; label: string }>>(\n'
  + '    [],\n'
  + '  );\n'
  + '  const [isLoading, setIsLoading] = useState(false);\n'
  + '  const [selectedLabel, setSelectedLabel] = useState<string | null>(null);\n'
  + '\n'
  + '  // Update internal value when `value` prop changes.\n'
  + '  useEffect(() => {\n'
  + '    setInternalValue(value ?? null);\n'
  + '  }, [value]);\n'
  + '\n'
  + '  // Load selected label when value changes.\n'
  + '  useEffect(() => {\n'
  + '    if (internalValue) {\n'
  + '      const loadLabel = async () => {\n'
  + '        try {\n'
  + '          const loadedOptions = await optionsLoader("");\n'
  + '          const selected = loadedOptions.find((o) => o.value === internalValue);\n'
  + '          setSelectedLabel(selected?.label ?? null);\n'
  + '        } catch (error) {\n'
  + '          console.error("Failed to load label:", error);\n'
  + '        }\n'
  + '      };\n'
  + '      loadLabel();\n'
  + '    } else {\n'
  + '      setSelectedLabel(null);\n'
  + '    }\n'
  + '  }, [internalValue, optionsLoader]);\n'
  + '\n'
  + '  // Create debounced options loader\n'
  + '  const debouncedLoadOptionsRef = useRef<ReturnType<typeof debounce> | null>(\n'
  + '    null,\n'
  + '  );\n'
  + '  const isInitialLoadRef = useRef(true);\n'
  + '\n'
  + '  useEffect(() => {\n'
  + '    // Create debounced function\n'
  + '    debouncedLoadOptionsRef.current = debounce(async (query: string) => {\n'
  + '      setIsLoading(true);\n'
  + '      try {\n'
  + '        const loadedOptions = await optionsLoader(query);\n'
  + '        setOptions(loadedOptions);\n'
  + '      } catch (error) {\n'
  + '        console.error("Failed to load options:", error);\n'
  + '        setOptions([]);\n'
  + '      } finally {\n'
  + '        setIsLoading(false);\n'
  + '      }\n'
  + '    }, 300);\n'
  + '\n'
  + '    return () => {\n'
  + '      // Cleanup debounced function on unmount or when optionsLoader changes\n'
  + '      debouncedLoadOptionsRef.current?.cancel();\n'
  + '      debouncedLoadOptionsRef.current = null;\n'
  + '    };\n'
  + '  }, [optionsLoader]);\n'
  + '\n'
  + '  // Load options when search query changes (debounced).\n'
  + '  useEffect(() => {\n'
  + '    // Load initial options immediately (no debounce for initial load).\n'
  + '    if (isInitialLoadRef.current) {\n'
  + '      isInitialLoadRef.current = false;\n'
  + '      (async () => {\n'
  + '        setIsLoading(true);\n'
  + '        try {\n'
  + '          const loadedOptions = await optionsLoader(searchQuery);\n'
  + '          setOptions(loadedOptions);\n'
  + '        } catch (error) {\n'
  + '          console.error("Failed to load options:", error);\n'
  + '          setOptions([]);\n'
  + '        } finally {\n'
  + '          setIsLoading(false);\n'
  + '        }\n'
  + '      })();\n'
  + '      return;\n'
  + '    }\n'
  + '\n'
  + '    // Use debounced loader for subsequent changes.\n'
  + '    if (debouncedLoadOptionsRef.current) {\n'
  + '      debouncedLoadOptionsRef.current(searchQuery);\n'
  + '    }\n'
  + '  }, [searchQuery, optionsLoader]);\n'
  + '\n'
  + '  // Update trigger width on mount and resize.\n'
  + '  useLayoutEffect(() => {\n'
  + '    if (triggerEl) {\n'
  + '      setTriggerWidth(triggerEl.offsetWidth);\n'
  + '\n'
  + '      const ro = new ResizeObserver(() => {\n'
  + '        const width = triggerEl.offsetWidth;\n'
  + '        if (width) {\n'
  + '          setTriggerWidth(triggerEl.offsetWidth);\n'
  + '        }\n'
  + '      });\n'
  + '      ro.observe(triggerEl);\n'
  + '\n'
  + '      return () => {\n'
  + '        ro.disconnect();\n'
  + '      };\n'
  + '    }\n'
  + '  }, [triggerEl]);\n'
  + '\n'
  + '  const baseStx = jss.hash({\n'
  + '    "--select-fontSize": theme.tokens.inputBaseMdFontSize,\n'
  + '    "--select-lineHeight": "1.375rem",\n'
  + '    "--select-borderColor": theme.tokens.inputBaseDefaultBorderColor,\n'
  + '    "--select-borderRadius": theme.tokens.inputBaseBorderRadius,\n'
  + '  });\n'
  + '\n'
  + '  const widthStx = jss.hash(calcWidthStx({ width }));\n'
  + '\n'
  + '  const popoverTriggerRender: PopoverTriggerRender = useCallback(\n'
  + '    ({ setRef, isOpen, onToggle }) => (\n'
  + '      <ComboboxTrigger\n'
  + '        id={id}\n'
  + '        ref={(el) => {\n'
  + '          setRef(el);\n'
  + '          setTriggerEl(el);\n'
  + '        }}\n'
  + '        placeholder={placeholder}\n'
  + '        className={classNames(baseStx, widthStx)}\n'
  + '        disabled={disabled}\n'
  + '        isOpen={isOpen}\n'
  + '        onToggle={onToggle}\n'
  + '        showLabel={selectedLabel}\n'
  + '      />\n'
  + '    ),\n'
  + '    [id, placeholder, baseStx, widthStx, disabled, selectedLabel],\n'
  + '  );\n'
  + '\n'
  + '  return (\n'
  + '    <Popover>\n'
  + '      <Popover.Trigger render={popoverTriggerRender} />\n'
  + '      <Popover.Portal\n'
  + '        onClickOutside={({ closePortal }) => closePortal()}\n'
  + '        render={({ setRef, togglePortal, isOpen, floatingStyles }) =>\n'
  + '          isOpen && (\n'
  + '            <ComboboxList\n'
  + '              ref={setRef}\n'
  + '              className={baseStx}\n'
  + '              style={floatingStyles}\n'
  + '              options={options}\n'
  + '              internalValue={internalValue}\n'
  + '              width={triggerWidth}\n'
  + '              searchQuery={searchQuery}\n'
  + '              onSearchQueryChange={setSearchQuery}\n'
  + '              isLoading={isLoading}\n'
  + '              onItemClicked={(v) => {\n'
  + '                if (!disabled) {\n'
  + '                  const selected = options.find((o) => o.value === v);\n'
  + '                  setInternalValue(v);\n'
  + '                  setSelectedLabel(selected?.label ?? null);\n'
  + '                  setSearchQuery("");\n'
  + '                  onChange?.(v);\n'
  + '                }\n'
  + '                togglePortal();\n'
  + '              }}\n'
  + '            />\n'
  + '          )\n'
  + '        }\n'
  + '      />\n'
  + '    </Popover>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'Combobox.displayName = "Combobox";\n'
  + '\n'
  + 'const calcWidthStx = resolveStyle2({\n'
  + '  width: {\n'
  + '    sm: { "--selectTrigger-w": "12rem" },\n'
  + '    md: { "--selectTrigger-w": "16rem" },\n'
  + '    lg: { "--selectTrigger-w": "20rem" },\n'
  + '    full: { "--selectTrigger-w": "100%" },\n'
  + '  },\n'
  + '});\n'
  + '\n'
  + 'export { Combobox };\n'
  ;

