  + 'import styles from "./combobox-trigger.module.scss";\n'
  + '\n'
  + 'type ComboboxTriggerProps = {\n'
  + '  id?: string;\n'
  + '  ref: Ref<HTMLButtonElement>;\n'
  + '  className?: string;\n'
  + '\n'
  + '  placeholder: string;\n'
  + '  disabled: boolean;\n'
  + '  isOpen: boolean;\n'
  + '  showLabel: string | null;\n'
  + '\n'
  + '  onToggle: () => void;\n'
  + '};\n'
  + '\n'
  + 'const ComboboxTrigger: FC<ComboboxTriggerProps> = (props) => {\n'
  + '  const {\n'
  + '    id,\n'
  + '    ref,\n'
  + '    className,\n'
  + '    placeholder,\n'
  + '    disabled,\n'
  + '    isOpen,\n'
  + '    showLabel,\n'
  + '    onToggle,\n'
  + '  } = props;\n'
  + '\n'
  + '  const theme = useTheme();\n'
  + '  const jss = useJss();\n'
  + '\n'
  + '  const triggerStx = jss.hash({\n'
  + '    "--selectTrigger-fontSize": theme.tokens.inputBaseMdFontSize,\n'
  + '    "--selectTrigger-lineHeight": theme.tokens.inputBaseMdLineHeight,\n'
  + '\n'
  + '    "--selectTrigger-h": theme.tokens.inputBaseMdHeight,\n'
  + '    "--selectTrigger-bdColor": theme.tokens.inputBaseDefaultBorderColor,\n'
  + '    "--selectTrigger-bdRadius": theme.tokens.inputBaseBorderRadius,\n'
  + '    "--selectTrigger-placeholderColor": theme.tokens.inputBasePlaceholderColor,\n'
  + '    "--selectTrigger-disabled-color": theme.colors.gray["600"],\n'
  + '    "--selectTrigger-disabled-bgColor": theme.colors.gray["000"],\n'
  + '    "--selectTrigger-disabled-borderColor": theme.colors.gray["200"],\n'
  + '    "--selectTrigger-focus-borderColor": theme.colors.blue["800"],\n'
  + '\n'
  + '    "--selectTrigger-px": "0.75rem",\n'
  + '  });\n'
  + '\n'
  + '  return (\n'
  + '    <button\n'
  + '      id={id}\n'
  + '      ref={ref}\n'
  + '      className={classNames(styles.comboboxTrigger, triggerStx, className)}\n'
  + '      onClick={() => !disabled && onToggle()}\n'
  + '      data-value-picked={showLabel == null ? undefined : "true"}\n'
  + '      data-disabled={disabled ? "true" : undefined}\n'
  + '      data-opened={isOpen ? "true" : undefined}\n'
  + '      type="button"\n'
  + '      role="combobox"\n'
  + '      aria-haspopup="listbox"\n'
  + '      aria-expanded="false"\n'
  + '    >\n'
  + '      <span style={{ flex: 1 }}>\n'
  + '        {showLabel !== null ? showLabel : placeholder}\n'
  + '      </span>\n'
  + '      <span className={styles.comboboxIcon}>\n'
  + '        <ChevronsUpDown size="62.5%" />\n'
  + '      </span>\n'
  + '    </button>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'ComboboxTrigger.displayName = "Combobox.Trigger";\n'
  + '\n'
  + 'export { ComboboxTrigger };\n'
  ;

